import React, { useRef, useEffect, useCallback } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

const CricketPage = () => {
  const cardsRef = useRef([]);

  // Using useCallback to ensure ScrollTrigger callback is memoized
  const createScrollTrigger = useCallback((card, index) => {
    gsap.set(card, { opacity: 0 });

    ScrollTrigger.create({
      trigger: card,
      start: 'top 80%',
      end: 'bottom 20%',
      scrub: true,
      onEnter: () => gsap.to(card, { opacity: 1, duration: 0.5 }),
      onLeave: () => gsap.to(card, { opacity: 0, duration: 0.5 }),
      onEnterBack: () => gsap.to(card, { opacity: 1, duration: 0.5 }),
      onLeaveBack: () => gsap.to(card, { opacity: 0, duration: 0.5 }),
    });
  }, []);

  useEffect(() => {
    document.title = 'Design on a Dime | Cricket';
    window.scrollTo(0, 0);

    cardsRef.current.forEach((card, i) => {
      createScrollTrigger(card, i);
    });
  }, [createScrollTrigger]);

  return (
    <section className="py-16 bg-primary-light border-t border-b border-blue-300" id="cricket">
      <div className="container mx-auto">
        <div className="relative space-y-40">
          {[ 
            "./images/Cricket/FF_PLAYERPROFILE.webp",
            "./images/Cricket/BAT GRIFF.webp",
            "./images/Cricket/doublemanhattan.webp",
            "./images/Cricket/MATCH_SUMMARY.webp",
            "./images/Cricket/PROJECTED.webp"
          ].map((src, index) => (
            <div ref={(el) => (cardsRef.current[index] = el)} key={index} className="card sticky top-40">
              <div className="bg-white border border-gray-200 rounded-lg shadow md:max-w-6xl mx-auto hover:bg-gray-100 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700 min-h-[200px]">
                <img 
                  loading="lazy" 
                  className="rounded-t-lg min-h-[200px] md:h-auto md:rounded-s-lg" 
                  src={src} 
                  alt={`Cricket Image ${index + 1}`} 
                />
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default CricketPage;
